sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float saturation;
uniform float vibrance;
half4 main(float2 coord) {
    half4 c = unpremul(image.eval(coord));
    float3 f = float3(c.rgb);
    float y = dot(f, float3(0.299, 0.587, 0.114));
    float2 uv = float2(dot(f, float3(-0.14713, -0.28886, 0.436)), dot(f, float3(0.615, -0.51499, -0.10001)));
    float vibGain = 1.0 + clamp(vibrance - 1.0, -1.0, 1.0) * max(1.0 - 2.52 * length(uv), 0.0);
    f = float3(y) + (f - float3(y)) * max(saturation + 1.0, 0.0) * vibGain;
    return half4(half3(saturate(f)) * c.a, c.a);
}
